{
  "mcpServers": {
    "guardlink": {
      "description": "GuardLink threat modeling as code (MIT). Security annotations in source comments, in its own annotation language (GAL), make up the threat model, so it changes with the code. The server runs locally over stdio and gives the agent about 30 guardlink_* tools to parse, validate and diff the model, list declared routes from untrusted input to a sink with no declared control, and export reports or SARIF. Results are deterministic queries over the declared annotations, not proof of real data flow or working mitigations. It reads files under the project root; report, dashboard and SARIF tools write files there. No account or API key; guardlink_threat_report calls an LLM provider only if ANTHROPIC_API_KEY, OPENAI_API_KEY, OPENROUTER_API_KEY or GOOGLE_API_KEY is already set, and otherwise returns a prompt for the calling agent. Needs Node 18+. Docs: https://docs.bugb.io/guardlink/",
      "command": "npx",
      "args": ["-y", "guardlink@2.7.1", "mcp"]
    }
  }
}
